"""Interactive deliberate-detail tradeoffs and complete arena accounting."""
import argparse
import json
from pathlib import Path


def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--out',type=Path,required=True);a=ap.parse_args();out=a.out.resolve();summary=json.loads((out/'summary.json').read_bytes());review=json.loads((out/'review.json').read_bytes());prior=json.loads((out.parent/'rmuc2027-dart-outpost/summary.json').read_bytes());payload={'before':prior['groups'],'after':summary['groups'],'totals':summary['totals'],'prior_totals':summary['prior_totals'],'file':summary['full_glb'],'images':[{'id':r['id'],'kind':r['kind'],'stages':r['stages'],'triangles':r['triangles'],'paths':{s:{v:str(out/r['images']/(s+'-'+v+'.webp'))for v in ['oblique','reverse','top','front','back','bottom','side']}for s in r['stages']}}for r in review['entries']]}
    html='''<!doctype html><html><head><meta charset="utf-8"><style>
body{font-family:var(--font-sans,system-ui);color:var(--foreground,#222);margin:0}p{line-height:1.45;margin:0 0 12px}.muted,small{color:var(--muted-foreground,#666)}.stats{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:14px 0}.stats>div{border-top:2px solid var(--border,#ccc);padding-top:9px}.stats b{display:block;font-size:23px}.stats small{display:block;margin-top:4px}table{border-collapse:collapse;width:100%;font-size:13px;margin:12px 0 16px}th,td{text-align:right;border-bottom:1px solid var(--border,#ddd);padding:8px 3px}th:first-child,td:first-child{text-align:left}.note{font-size:13px}.controls{display:grid;grid-template-columns:3fr 1.3fr 1fr;gap:10px;margin:12px 0}label{font-size:13px}select{display:block;max-width:100%;width:100%;margin-top:5px;padding:8px;color:inherit;background:var(--background,white);border:1px solid var(--border,#ccc);border-radius:5px;font:inherit}.buttons{display:flex;gap:7px;flex-wrap:wrap;margin-top:16px}button{font:inherit;font-size:12px;padding:6px 10px;border:1px solid var(--border,#ccc);border-radius:5px;color:inherit;background:var(--secondary,#eee);cursor:pointer}#labels{display:grid;grid-template-columns:1fr 1fr;text-align:center;font-size:13px;gap:6px;margin-bottom:6px}img{display:block;width:100%;height:auto;border-radius:6px}summary{cursor:pointer;margin:16px 0}.wrap{overflow-x:auto}@media(max-width:480px){.controls{grid-template-columns:1fr 1fr}.controls label:first-child{grid-column:1/-1}.stats b{font-size:19px}table{font-size:12px}}
</style></head><body><p><b>More aggressive equipment geometry</b><br><span class="muted">Compact hardware omitted · local LOD · fitted branded end caps</span></p>
<div class="wrap"><table><thead><tr><th>Both field placements</th><th>Visual before → after</th><th>Reduction</th><th>Contact budget before → after*</th></tr></thead><tbody id="groups"></tbody></table></div>
<div class="stats"><div><b id="visual"></b>whole-arena placed visual triangles<small id="visual-save"></small></div><div><b id="contact"></b>whole-arena contact planning budget*<small id="contact-save"></small></div></div>
<p class="note"><b>Deliberate changes:</b> small fasteners and connector/chip details disappear. Two blue motor end caps go from 3,798 to 44 triangles each; engraved branding and shallow rear recesses fill. Light surfaces, neighboring opaque geometry and source scene order are protected.</p>
<div class="buttons"><button data-case="dart-station / complete">Full Dart</button><button data-case="outpost / complete">Full Outpost</button><button data-case="Dart engraved end cap / close-up">End-cap close-up</button><button data-case="dart-station/frame / cutaway">Frame interior</button></div>
<div class="controls"><label>Model / mesh<select id="part"></select></label><label>Pass<select id="stage"></select></label><label>View<select id="view"><option>oblique</option><option>reverse</option><option>top</option><option>front</option><option>back</option><option>bottom</option><option>side</option></select></label></div><div id="labels"></div><img id="image" alt="Matched approved and more aggressive equipment views"><p class="note muted" id="kind"></p>
<p class="note muted">*Contact is prospective accounting, not a live physics capture. Compact omitted pieces are under 17 mm on every axis and close to retained backing. Structural LOD uses 4 mm visual / 6 mm contact sample limits; fitted end caps use a separate 9 mm local allowance. All 21 qualified projectile paths retain 17 mm clearance. The cheaper prior collider is retained when it wins.</p>
<details><summary>Complete arena breakdown and shared storage</summary><div class="wrap"><table><thead><tr><th>Group</th><th>Placed visuals</th><th>Contact budget*</th></tr></thead><tbody id="arena"></tbody></table></div><p class="note muted" id="storage"></p></details>
<script>const d=__DATA__,num=n=>n.toLocaleString(),old=Object.fromEntries(d.before.map(r=>[r.group,r]));for(const name of ['Dart station','Outpost']){const a=d.after.find(r=>r.group===name),b=old[name],tr=document.createElement('tr');for(const v of [name,`${num(b.visual_placed)} → ${num(a.visual_placed)}`,((1-a.visual_placed/b.visual_placed)*100).toFixed(1)+'%',`${num(b.collision_budget_placed)} → ${num(a.collision_budget_placed)}`]){const td=document.createElement('td');td.textContent=v;tr.append(td)}document.getElementById('groups').append(tr)}for(const [id,key]of[['visual','visual_placed'],['contact','collision_budget_placed']]){document.getElementById(id).textContent=num(d.totals[key]);document.getElementById(id+'-save').textContent=num(d.prior_totals[key]-d.totals[key])+' fewer · '+((1-d.totals[key]/d.prior_totals[key])*100).toFixed(1)+'%'}for(const r of d.after){const tr=document.createElement('tr');for(const v of[r.group,num(r.visual_placed),num(r.collision_budget_placed)]){const td=document.createElement('td');td.textContent=v;tr.append(td)}document.getElementById('arena').append(tr)}document.getElementById('storage').textContent=`${num(d.totals.stored_triangles)} shared mesh triangles · ${(d.file.bytes/1e6).toFixed(1)} MB GLB · 116 definitions · 171 source placements. No orphan triangles; runtime assets unchanged.`;const part=document.getElementById('part'),stage=document.getElementById('stage'),view=document.getElementById('view');d.images.forEach((r,i)=>part.add(new Option(r.id,i)));function show(){const r=d.images[+part.value],s=stage.value;document.getElementById('image').src=r.paths[s][view.value];document.getElementById('labels').replaceChildren(...['reference',s].map(x=>{const e=document.createElement('span');e.textContent=(x==='reference'?'Approved reference':s==='micro'?'Compact omission only':'Final candidate')+' · '+num(r.triangles[x])+' tris';return e}));document.getElementById('kind').textContent=r.kind==='profile'?'Engraved lettering and rear cavity intentionally filled. The rounded outline and original blue PBR remain. This motor end cap is a structural detail.':r.kind==='collision'?'Collision only · diagnostic blue · selected lower-cost contact mesh.':'Source-colored visual model · '+(s==='micro'?'surviving positions, normals, materials and owner IDs are exact.':'compact omission, then component-local LOD and selected profile envelopes.')}function model(){const r=d.images[+part.value];stage.replaceChildren(...r.stages.map(s=>new Option(s==='micro'?'Omission only':'Final',s)));stage.value='candidate';show()}part.onchange=model;stage.onchange=view.onchange=show;document.querySelectorAll('button[data-case]').forEach(b=>b.onclick=()=>{part.value=d.images.findIndex(r=>r.id===b.dataset.case);model()});part.value=0;model();</script></body></html>'''
    (out/'review.html').write_text(html.replace('__DATA__',json.dumps(payload)));print(out/'review.html')


if __name__=='__main__':main()
